```python
import psutil
import subprocess

def get_cpu_usage():
    return psutil.cpu_percent(interval=1)

def optimize_build_process():
    # Example: Use efficient shell commands
    subprocess.run(['mvn', 'clean', 'package', '-T', '4'], check=True)

def parallelize_builds():
    # Example: Run builds in parallel using subprocess
    processes = []
    for module in ['moduleA', 'moduleB', 'moduleC']:
        process = subprocess.Popen(['mvn', 'clean', 'package', '-pl', module])
        processes.append(process)

    # Wait for all processes to complete
    for process in processes:
        process.wait()

def main():
    cpu_usage = get_cpu_usage()
    print(f"Current CPU usage: {cpu_usage}%")

    if cpu_usage > 70:
        print("Optimizing build process...")
        optimize_build_process()
        parallelize_builds()
        new_cpu_usage = get_cpu_usage()
        print(f"New CPU usage: {new_cpu_usage}%")

if __name__ == "__main__":
    main()
```

