from jenkins import Jenkins

def create_jenkins_instance():
    return Jenkins('http://localhost:8080', username='admin', password='admin', timeout=10)

def configure_parallel_builds(jenkins_instance):
    # Example: Create a new job with parallel builds
    job_name = 'SimulationPlatformParallelBuilds'
    config_xml = """
    <project>
        <actions/>
        <description>Simulation Platform with Parallel Builds</description>
        <keepDependencies>false</keepDependencies>
        <properties/>
        <scm class="hudson.plugins.git.GitSCM" plugin="git@4.10.0">
            <configVersion>2</configVersion>
            <userRemoteConfigs>
                <hudson.plugins.git.UserRemoteConfig>
                    <url>https://github.com/your-repo/simulation-platform.git</url>
                </hudson.plugins.git.UserRemoteConfig>
            </userRemoteConfigs>
            <branches>
                <hudson.plugins.git.BranchSpec>
                    <name>*/master</name>
                </hudson.plugins.git.BranchSpec>
            </branches>
            <doGenerateSubmoduleConfigurations>false</doGenerateSubmoduleConfigurations>
            <submoduleCfg class="list"/>
            <extensions/>
        </scm>
        <canRoam>true</canRoam>
        <disabled>false</disabled>
        <blockBuildWhenDownstreamBuilding>false</blockBuildWhenDownstreamBuilding>
        <blockBuildWhenUpstreamBuilding>false</blockBuildWhenUpstreamBuilding>
        <triggers/>
        <concurrentBuild>false</concurrentBuild>
        <builders>
            <hudson.tasks.Shell>
                <command>
                    #!/bin/bash
                    mvn clean package -T 4
                </command>
            </hudson.tasks.Shell>
        </builders>
        <publishers/>
        <buildWrappers/>
    </project>
    """
    jenkins_instance.create_job(job_name, config_xml)

def deploy_simulation_platform():
    jenkins_instance = create_jenkins_instance()
    job_name = 'SimulationPlatformParallelBuilds'
    queue_item = jenkins_instance.build_job(job_name)
    print(f"Build queued with item ID: {queue_item}")

if __name__ == "__main__":
    jenkins_instance = create_jenkins_instance()
    configure_parallel_builds(jenkins_instance)
    deploy_simulation_platform()
```

