    agent any

    parameters {
        choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Select the environment to deploy to')
    }

    stages {
        stage('Source Checkout') {
            steps {
                script {
                    try {
                        checkout scm
                        echo "Source checkout successful"
                    } catch (Exception e) {
                        echo "Source checkout failed: ${e}"
                        error "Source checkout failed: ${e}"
                    }
                }
            }
        }

        stage('Build') {
            steps {
                script {
                    try {
                        sh 'make build'
                        echo "Build successful"
                    } catch (Exception e) {
                        echo "Build failed: ${e}"
                        error "Build failed: ${e}"
                    }
                }
            }
        }

        stage('Test') {
            steps {
                script {
                    try {
                        sh 'make test'
                        echo "Tests successful"
                    } catch (Exception e) {
                        echo "Tests failed: ${e}"
                        error "Tests failed: ${e}"
                    }
                }
            }
        }

        stage('Package') {
            steps {
                script {
                    try {
                        sh 'make package'
                        echo "Packaging successful"
                    } catch (Exception e) {
                        echo "Packaging failed: ${e}"
                        error "Packaging failed: ${e}"
                    }
                }
