                    } catch (Exception e) {
                        echo "Staging deployment failed: ${e}"
                        error "Staging deployment failed: ${e}"
                    }
                }
            }
        }

        stage('Deploy Dev') {
            when {
                expression { params.ENVIRONMENT == 'dev' }
            }
            steps {
                script {
                    try {
                        sh 'make deploy-dev'
                        echo "Development deployment successful"
                    } catch (Exception e) {
                        echo "Development deployment failed: ${e}"
                        error "Development deployment failed: ${e}"
                    }
                }
            }
        }
