### Example Jenkinsfile with Docker and Multi-Stage Builds

Here's an example Jenkinsfile that demonstrates how to use Docker and multi-stage builds to optimize your pipeline:

```groovy
pipeline {
    agent none

    stages {
        stage('Checkout') {
            agent any
            steps {
                checkout scm
            }
        }

        stage('Build') {
            agent {
                dockerfile {
                    filename 'Dockerfile'
                    dir 'build'
                }
            }
            steps {
                script {
                    def buildImage = docker.build("my-app:${env.BUILD_ID}")
                    buildImage.inside {
                        sh 'make build'
                    }
                }
            }
        }

        stage('Test') {
            agent {
                docker {
                    image 'my-app:test'
                    args '-v /tmp:/tmp'
                }
            }
            steps {
                script {
                    docker.image('my-app:test').inside {
                        sh 'make test'
                    }
                }
            }
        }

        stage('Deploy') {
            agent any
            steps {
                script {
                    def deployImage = docker.build("my-app:latest")
                    deployImage.push()
                }
            }
        }
    }

    post {
        always {
            cleanWs()
        }
    }
}
```

