### Updated Terraform Configuration

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Define lists for subnets and tiers
variable "subnets" {
  default = [
    { cidr_block = "10.0.1.0/24", az = "us-west-2a", type = "public" },
    { cidr_block = "10.0.2.0/24", az = "us-west-2b", type = "public" },
    { cidr_block = "10.0.3.0/24", az = "us-west-2a", type = "private" },
    { cidr_block = "10.0.4.0/24", az = "us-west-2b", type = "private" },
    # Add more subnets as needed
  ]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "public-route-table"
  }
}

# Create Route Table for Private Subnets
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "private-route-table"
  }
}

# Create Subnets
resource "aws_subnet" "all" {
  count = length(var.subnets)
  cidr_block = element(var.subnets, count.index).cidr_block
  vpc_id = aws_vpc.main.id
  availability_zone = element(var.subnets, count.index).az
  tags = {
    Name = format("%s-subnet%d", element(var.subnets, count.index).type, count.index + 1)
  }
}

# Create Route Table Associations for Public Subnets
resource "aws_route_table_association" "public" {
  count = length([for s in var.subnets : s if s.type == "public"])
  subnet_id = element([for s in aws_subnet.all : s.id if s.tags.Name =~ "public-subnet.*"], count.index)
  route_table_id = aws_route_table.public.id
}

# Create Route Table Associations for Private Subnets
resource "aws_route_table_association" "private" {
  count = length([for s in var.subnets : s if s.type == "private"])
  subnet_id = element([for s in aws_subnet.all : s.id if s.tags.Name =~ "private-subnet.*"], count.index)
  route_table_id = aws_route_table.private.id
}

# Create Security Group for Public Subnets
