Great! Automating 95% of your access control tasks is a significant goal. To help you achieve this, let's focus on refining and expanding your existing scripts to cover more aspects of your access control processes. Here are some steps and best practices to guide you:

### Step 1: Modularize Your Scripts

Break down your scripts into smaller, reusable components. This will make your code more maintainable and easier to extend.

#### Example Structure

```python
# iam_utils.py
import boto3
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def create_iam_client():
    """Create an IAM client."""
    return boto3.client('iam')

def create_iam_role(role_name, trust_policy):
    """Create an IAM role."""
    iam = create_iam_client()
    try:
        response = iam.create_role(
            RoleName=role_name,
            AssumeRolePolicyDocument=trust_policy
        )
        logger.info(f"Created IAM role: {role_name}")
        return response
    except iam.exceptions.EntityAlreadyExistsException:
        logger.warning(f"IAM role {role_name} already exists.")
    except Exception as e:
        logger.error(f"Error creating IAM role: {e}")
        raise

def attach_policy_to_role(role_name, policy_arn):
    """Attach a policy to an IAM role."""
    iam = create_iam_client()
    try:
        iam.attach_role_policy(RoleName=role_name, PolicyArn=policy_arn)
        logger.info(f"Attached policy {policy_arn} to role {role_name}")
    except Exception as e:
        logger.error(f"Error attaching policy to role: {e}")
        raise

# main_access_control.py
from iam_utils import create_iam_role, attach_policy_to_role

def main():
    role_name = 'MyIAMRole'
    trust_policy = """
    {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Effect": "Allow",
                "Principal": {
                    "Service": "ec2.amazonaws.com"
                },
                "Action": "sts:AssumeRole"
            }
        ]
    }
    """
    policy_arn = 'arn:aws:iam::aws:policy/AmazonS3FullAccess'

    # Create IAM role
    create_iam_role(role_name, trust_policy)

    # Attach policy to IAM role
    attach_policy_to_role(role_name, policy_arn)

if __name__ == '__main__':
    main()
```

### Step 2: Use Configuration Files

Manage your configuration settings (like role names and policy ARNs) in a separate configuration file. This makes it easier to update settings without modifying the script.

#### Example Configuration File (`config.yaml`)

```yaml
roles:
  - name: MyIAMRole
    trust_policy: |
      {
          "Version": "2012-10-17",
          "Statement": [
              {
                  "Effect": "Allow",
                  "Principal": {
                      "Service": "ec2.amazonaws.com"
                  },
                  "Action": "sts:AssumeRole"
              }
          ]
      }
    policies:
      - arn:aws:iam::aws:policy/AmazonS3FullAccess
```

#### Example Script to Read Configuration

```python
import yaml
from iam_utils import create_iam_role, attach_policy_to_role

def load_config(config_file):
    """Load configuration from a YAML file."""
    with open(config_file, 'r') as file:
        config = yaml.safe_load(file)
    return config

def main():
    config_file = 'config.yaml'
    config = load_config(config_file)

    for role in config['roles']:
        role_name = role['name']
        trust_policy = role['trust_policy']
        policies = role['policies']

        # Create IAM role
        create_iam_role(role_name, trust_policy)

        # Attach policies to IAM role
        for policy_arn in policies:
            attach_policy_to_role(role_name, policy_arn)

if __name__ == '__main__':
    main()
