```python
import os
import re
from collections import defaultdict

def generate_release_notes(version):
    # Fetch commit messages from Git
    commits = os.popen(f"git log --pretty=format:'%h %s' {version}..HEAD").read()

    # Parse commit messages for release notes
    release_notes = defaultdict(list)

    for line in commits.splitlines():
        commit_hash, message = line.split(maxsplit=1)
        # Assuming commit messages follow a pattern like "fix: description" or "feat: description"
        match = re.match(r"(fix|feat): (.*)", message)
        if match:
            category, description = match.groups()
            release_notes[category].append((commit_hash, description))

    # Format the release notes
    formatted_release_notes = []
    for category, items in release_notes.items():
        formatted_release_notes.append(f"## {category.capitalize()}s\n")
        for commit_hash, description in items:
            formatted_release_ = f"- [{commit_hash}] {description}\n"
            formatted_release_notes.append(formatted_release_)

    return "".join(formatted_release_notes)

# Example usage
