import os
import re
from collections import defaultdict

def generate_release_notes(version):
    # Fetch commit messages from Git
    commits = os.popen(f"git log --pretty=format:'%h %s' {version}..HEAD").read()

    # Parse commit messages for release notes
    release_notes = defaultdict(lambda: defaultdict(list))

    for line in commits.splitlines():
        commit_hash, message = line.split(maxsplit=1)
        # Extract all categories and descriptions from the commit message
        matches = re.findall(r"(fix|feat)\(([^)]*)\): (.*)", message)
        if matches:
            for category, scope, description in matches:
                if scope:
                    scope = scope.strip('()')
                else:
                    scope = "general"
                release_notes[category][scope].append((commit_hash, description))

    # Format the release notes
    formatted_release_notes = []
    for category in sorted(release_notes.keys()):
        formatted_release_notes.append(f"## {category.capitalize()}s\n")
        for scope in sorted(release_notes[category].keys()):
            formatted_release_notes.append(f"### {scope.capitalize()}\n")
            for commit_hash, description in release_notes[category][scope]:
                formatted_release_notes.append(f"- [{commit_hash}] {description}\n")

    return "".join(formatted_release_notes)

# Example usage
