pipeline {
    agent any

    stages {
        stage('Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/your-repo.git'
            }
        }

        stage('Build and Test') {
            matrix {
                axes {
                    axis {
                        name 'BUILD_TYPE'
                        values 'unit', 'integration', 'functional'
                    }
                }
                stages {
                    stage('Authenticate') {
                        steps {
                            script {
                                def authSuccess = false
                                def maxRetries = 3
                                def retryCount = 0

                                while (!authSuccess && retryCount < maxRetries) {
                                    try {
                                        // Perform authentication check
                                        sh 'your-auth-command'
                                        authSuccess = true
                                    } catch (Exception e) {
                                        retryCount++
                                        echo "Authentication failed, retrying (${retryCount}/${maxRetries})"
                                        sleep(time: 5, unit: 'SECONDS')
                                    }
                                }

                                if (!authSuccess) {
                                    error 'Authentication failed after maximum retries'
                                }
                            }
                        }
                    }

                    stage('Build') {
                        steps {
                            script {
                                // Perform build steps
                                sh 'your-build-command'
                            }
                        }
                    }

                    stage('Test') {
                        steps {
                            script {
                                // Perform test steps
                                sh 'your-test-command'
                            }
                        }
                    }
                }
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        success {
            echo 'Build succeeded!'
        }
        failure {
            echo 'Build failed!'
            // Capture detailed logs
            sh 'cat /path/to/logs'
        }
    }
}
```

